    public Object getValueAt(String name) {
        return values.get(name);
    }

    public void setValueAt(String name, Object value) {
        if (name != null) {
            values.put(name, value);
        }
    }

    public String getErrorCategory() {
        return (String) values.get("ErrorCategory");
    }

    public void setErrorCategory(String category) {
        values.put("ErrorCategory", category);
    }

    public String getErrorNumber() {
        return (String) values.get("ErrorNumber");
    }

    public void setErrorNumber(String number) {
        values.put("ErrorNumber", number);
    }

    public String getErrorDescription() {
        return (String) values.get("ErrorDescription");
    }

    public void setErrorDescription(String description) {
        values.put("ErrorDescription", description);
    }
}

