}

package com.company.generated.units.u2e52a65fe1ce;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class ValidationFailedHandlerTest {

    @Test
    public void testValidationFailedExecution() {
        ValidationFailedHandler handler = new ValidationFailedHandler();
        ValidationContext context = new ValidationContext();

        ValidationResult result = handler.handle(context);

        assertEquals(0, result.getReturnCode());
        assertEquals("10", context.getErrorCategory());
        assertEquals("2", context.getErrorNumber());
        assertEquals("Validation failed: required field missing or invalid", context.getErrorDescription());
        assertEquals("10", result.getErrorCategory());
        assertEquals("2", result.getErrorNumber());
        assertEquals("Validation failed: required field missing or invalid", result.getErrorDescription());
    }
}
